from collections import Counter
def f(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    segs=[]
    seen=set()
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]
                for dr,dc in ((1,1),(1,-1)):
                    # collect segment through (r,c) in this direction
                    cells=[(r,c)]
                    rr,cc=r-dr,c-dc
                    while 0<=rr<h and 0<=cc<w and g[rr][cc]==col:
                        cells.append((rr,cc)); rr-=dr; cc-=dc
                    rr,cc=r+dr,c+dc
                    while 0<=rr<h and 0<=cc<w and g[rr][cc]==col:
                        cells.append((rr,cc)); rr+=dr; cc+=dc
                    if len(cells)>=2:
                        segs.append((col,cells,(dr,dc)))
                        seen.update(cells)
    # candidates: extend from each end along the line direction
    cands=[]
    for col,cells,(dr,dc) in segs:
        for end,(sdr,sdc) in ((cells[-1],(dr,dc)),(cells[0],(-dr,-dc))):
            run=[]; rr,cc=end[0]+sdr,end[1]+sdc
            while 0<=rr<h and 0<=cc<w and g[rr][cc]==bg:
                run.append((rr,cc)); rr+=sdr; cc+=sdc
            if run and (rr,cc)==(h if sdr>0 else -1 if sdr<0 else rr, w if sdc>0 else -1 if sdc<0 else cc) or (run and not (0<=rr<h and 0<=cc<w)):
                cands.append((len(run),col,run))
    if not cands: return [r[:] for r in g]
    cands.sort(reverse=True)
    L,col,run=cands[0]
    out=[r[:] for r in g]
    for r,c in run: out[r][c]=col
    return out
